new_sub=r'''function subscriptionPage(){const x=S.own.subscription||{},s=S.subscriptionStats||{bookings:0,clients:0,notifications:0,period_days:30},trial=x.status==='trial',expired=x.status==='expired',active=x.status==='active',activeDays=active&&x.paid_until?Math.max(0,Math.ceil((x.paid_until-Date.now()/1000)/86400)):null,status=trial?`Осталось ${x.days_left||0} дн.`:expired?'Доступ приостановлен':activeDays!==null?`Осталось ${activeDays} дн.`:'Подписка активна',perBooking=s.bookings?Math.max(1,Math.round(590/s.bookings)):null;return `${heading('Подписка','Доступ к Takt и польза за текущий период.')}<section class="subscription-v8 ${expired?'expired':''}"><div class="subscription-v8-top"><div><span class="eyebrow">${trial?'ПРОБНЫЙ ПЕРИОД':expired?'ДОСТУП ПРИОСТАНОВЛЕН':'TAKT'}</span><h2>590 ₽ <small>/ месяц</small></h2><p>Один тариф. Все функции записи включены.</p></div><span class="subscription-status ${expired?'expired':''}">${esc(status)}</span></div><div class="subscription-value"><span class="eyebrow">TAKT ЗА ПОСЛЕДНИЕ ${s.period_days} ДНЕЙ</span><h3>${s.bookings} записей · ${s.clients} клиентов · ${s.notifications} уведомлений</h3>${perBooking?`<p>При текущей активности подписка — примерно <strong>${perBooking} ₽ за запись</strong>.</p>`:'<p>Когда появятся записи, здесь будет видно, сколько работы Takt взял на себя.</p>'}</div><div class="subscription-features"><span>✓ Онлайн-запись</span><span>✓ Расписание и клиенты</span><span>✓ Telegram-уведомления</span><span>✓ Подтверждение визитов</span><span>✓ Отзывы и статистика</span><span>✓ Поддержка</span></div>${expired?'<p class="subscription-safe">Ваши клиенты, услуги и история сохранены. После продления ничего настраивать заново не нужно.</p>':''}${x.payment_url?`<a class="primary wide" href="${esc(x.payment_url)}" target="_blank" rel="noopener">${expired?'Возобновить доступ':'Продлить Takt'}</a>`:'<p class="note">Платёжный способ будет подключён отдельно. Ваши данные сохраняются независимо от статуса подписки.</p>'}</section>`}
'''
a=regex_once(a,r"function subscriptionPage\(\)\{[\s\S]*?\nfunction servicesPage",new_sub+"function servicesPage",'subscription page')

# settings additions: appearance/help/docs, one guide, v8
a=replace_once(a,"<details class=\"settings-section\"><summary>Часовой пояс <small>Время ваших записей</small></summary>${timezoneField(x.timezone)}</details><div class=\"form-error\"","<details class=\"settings-section\"><summary>Часовой пояс <small>Время ваших записей</small></summary>${timezoneField(x.timezone)}</details><details class=\"settings-section settings-accent\"><summary>Интерфейс <small>Язык и тема приложения</small></summary>${languageControl()}${themeControl()}</details><details class=\"settings-section settings-accent\"><summary>Помощь <small>Ответы, документы и поддержка</small></summary><div class=\"settings-links-v8\"><button type=\"button\" data-page=\"help\">Вопросы и ответы</button><button type=\"button\" data-page=\"legal\">Документы и конфиденциальность</button><button type=\"button\" id=\"support\">Поддержка</button></div></details><div class=\"form-error\"",'settings appearance help')
a=replace_once(a,"<section class=\"settings-system\"><div><strong>Takt 7.2</strong><span>Версия приложения</span></div><button class=\"text-button\" id=\"guide\">Как это работает</button></section>","<section class=\"settings-system settings-system-v8\"><div><strong>Takt 8.0</strong><span>Версия приложения</span></div><button class=\"guide-highlight\" id=\"guide\">Как это работает</button></section>",'settings footer')
# horizon input friendlier
