# controls + help/legal pages before analytics
helpers=r'''function languageControl(){return `<div class="preference-control"><span>Язык приложения</span><div class="choice-pills">${LANGUAGES.map(([code,flag,name])=>`<button type="button" data-language="${code}" class="${S.language===code?'selected':''}">${flag} ${name}</button>`).join('')}</div></div>`}
function themeControl(){const mode=S.appSettings?.theme||storedTheme();return `<div class="preference-control"><span>Тема оформления</span><div class="choice-pills">${[['system','Как в системе'],['light','Светлая'],['dark','Тёмная']].map(([v,t])=>`<button type="button" data-theme="${v}" class="${mode===v?'selected':''}">${t}</button>`).join('')}</div></div>`}
function helpPage(){const rows=faqCopy(S.language);return `${heading('Вопросы и ответы','Короткие ответы по работе Takt.')}<div class="faq-list">${rows.map(([q,ans])=>`<details class="faq-card"><summary>${esc(q)}</summary><p>${esc(ans)}</p></details>`).join('')}</div><section class="help-actions-v8"><button class="primary" id="support">Написать в поддержку</button><button class="secondary" data-page="legal">Документы</button></section>`}
function legalPage(){const docs=['policy','consent','terms'];return `${heading('Документы и конфиденциальность','Документы всегда доступны в настройках клиента и специалиста.')}<div class="legal-cards">${docs.map(type=>{const [title,paragraphs]=legalDoc(type,S.language);return `<article class="legal-card"><span class="eyebrow">TAKT · ${type.toUpperCase()}</span><h2>${esc(title)}</h2><p>${esc(paragraphs[0])}</p><button class="secondary" data-legal="${type}">Открыть документ</button></article>`}).join('')}</div><p class="legal-version">Принято: ${S.appSettings?.consent_at?new Date(S.appSettings.consent_at*1000).toLocaleDateString(localeFor(S.language)):'—'} · версия ${esc(S.appSettings?.versions?.policy||'2026-10-05-v1')}</p>`}
'''
a=replace_once(a,"function analyticsPage(){",helpers+"function analyticsPage(){",'help legal helpers')

# profile same quality, settings for client and specialist
new_profile=r'''function profile(){const app=S.appSettings||{};return `${heading(isClient()?'Мой профиль':'Помощь и аккаунт',isClient()?'Настройки клиента и ваши визиты.':'Аккаунт, интерфейс и помощь Takt.')}<section class="editor-card profile-v8">${imageTag('',S.me?.name)}<div><span class="eyebrow">${isClient()?'КЛИЕНТ':'СПЕЦИАЛИСТ'}</span><h2>${esc(S.me?.name||'Гость')}</h2><p class="note">${isClient()?'Ваши записи доступны только вам и выбранному специалисту.':'Вы управляете своим пространством, услугами и клиентами.'}</p></div></section><section class="editor-card profile-settings-v8"><h3>Интерфейс</h3>${languageControl()}${themeControl()}</section><section class="profile-link-grid"><button data-page="help"><strong>Вопросы и ответы</strong><span>Подсказки по работе Takt</span></button><button data-page="legal"><strong>Документы и конфиденциальность</strong><span>${app.consent_at?'Согласие сохранено':'Открыть документы'}</span></button><button id="support"><strong>Поддержка</strong><span>Сообщение получит администратор Takt</span></button></section>${!isClient()&&S.me?.owner?'<section class="editor-card"><h3>Подключение Telegram · владелец</h3><button class="secondary" id="connect-bot">Обновить настройки бота</button></section>':''}`}
'''
a=regex_once(a,r"function profile\(\)\{[\s\S]*?\nfunction openSheet",new_profile+"function openSheet",'profile')

# openSheet localization
a=replace_once(a,"sheet.innerHTML=`<div class=\"sheet-grip\"></div><div class=\"dialog-head ${back?'has-back':''}\">${backButton}<h2>${esc(title)}</h2><button class=\"close\" data-close aria-label=\"Закрыть\">×</button></div>${html}`;if(!sheet.open)sheet.showModal()","sheet.innerHTML=`<div class=\"sheet-grip\"></div><div class=\"dialog-head ${back?'has-back':''}\">${backButton}<h2>${esc(title)}</h2><button class=\"close\" data-close aria-label=\"Закрыть\">×</button></div>${html}`;localizeDOM(sheet,S.language);if(!sheet.open)sheet.showModal()",'sheet localization')

# visit/client details + messaging + phone helper
new_visit=r'''function visitActions(id){const b=S.bookings.find(x=>x.id===id);if(!b)return;const admin=!isClient(),allowed=active(b)&&(admin||b.starts_at>Date.now()/1000+(S.tenant?.cancel_hours||0)*3600),canMessage=admin&&/^[0-9]+$/.test(String(b.user_id));openSheet('Детали записи',`<div class="booking-review"><h3>${esc(b.service_name)}</h3><p>${dateLabel(date(b.starts_at))} · ${time(b.starts_at)}–${time(b.ends_at)}</p><span class="badge ${b.status}">${labels[b.status]}</span>${admin?(()=>{const a=attendanceInfo(b);return `<div class="visit-attendance"><span class="attendance visit-confirmation ${a[0]}">${a[1]}</span>${a[2]?`<small>${a[2]}</small>`:''}</div>`})():''}<p>${esc(b.name)} · ${esc(b.phone)}</p>${b.details?`<p>${esc(b.details)}</p>`:''}<strong>${money(b.price)}</strong></div><div class="sheet-actions">${!admin&&b.status==='done'&&!b.review_rating?`<button class="primary" data-review="${b.id}">⭐ Оставить отзыв</button>`:''}${admin&&b.status==='pending'?`<button class="primary" data-status="confirmed" data-id="${id}">Подтвердить</button>`:''}${admin&&b.status==='confirmed'?`<button class="primary" data-status="done" data-id="${id}">Завершить визит</button>`:''}${canMessage?`<button class="secondary" data-message-client="${esc(b.user_id)}">Написать клиенту</button>`:''}${admin&&b.phone?`<button class="secondary" data-call="${esc(b.phone)}">Позвонить</button>`:''}${allowed?` ${admin||S.tenant?.allow_reschedule?`<button class="secondary" data-move="${id}">Перенести</button>`:''}<button class="danger" data-cancel="${id}">Отменить запись</button>`:''}</div><div class="form-error" role="alert"></div>`)}
'''
a=regex_once(a,r"function visitActions\(id\)\{[\s\S]*?\nfunction supportEditor",new_visit+"function supportEditor",'visit actions')
new_msg=r'''async function clientMessageEditor(id){let x=S.clients.find(c=>String(c.id)===String(id));if(!x&&S.own)try{S.clients=await api('/v2/clients?company='+S.own.id);x=S.clients.find(c=>String(c.id)===String(id))}catch{}if(!x){const b=S.bookings.find(b=>String(b.user_id)===String(id));if(b)x={id:b.user_id,name:b.name,phone:b.phone,telegram_username:''}}if(!x){toast('Клиент не найден');return}const direct=x.telegram_username?`<button type="button" class="secondary wide" data-open-telegram="${esc(x.telegram_username)}">Открыть личный чат в Telegram</button>`:'';openSheet('Написать клиенту',`${direct}<form id="client-message-form" data-client="${esc(x.id)}"><p class="dialog-sub">${esc(x.name)} · сообщение придёт от Takt с названием вашего кабинета.</p><label>Сообщение<textarea name="message" maxlength="1000" required placeholder="Например: появилось удобное время на завтра…"></textarea></label><div class="form-error" role="alert"></div><button class="primary wide" type="submit">Отправить через Takt</button></form>`)}
function callClient(phone){const clean=String(phone||'').replace(/[^+0-9]/g,'');if(clean.replace(/\D/g,'').length<7){toast('Телефон клиента недоступен');return}location.href='tel:'+clean}
'''
a=regex_once(a,r"function clientMessageEditor\(id\)\{[\s\S]*?\nfunction openTelegramClient",new_msg+"function openTelegramClient",'client message helper')
new_details=r'''function clientDetails(id){const x=S.clients.find(x=>String(x.id)===String(id));if(!x)return;const canMessage=/^[0-9]+$/.test(String(x.id));openSheet(x.name,`<div class="client-detail72"><div class="client-detail72-contact"><div><span>Телефон</span><strong>${esc(x.phone||'—')}</strong></div><div class="client-detail72-actions">${canMessage?`<button class="primary" data-message-client="${esc(id)}">Написать</button>`:''}${x.phone?`<button class="secondary" data-call="${esc(x.phone)}">Позвонить</button>`:''}</div></div><div class="client-summary"><span>${x.visits} завершённых визитов</span><strong>${money(x.revenue)}</strong></div><p class="note">${x.next_visit?'Ближайший визит: '+dateLabel(date(x.next_visit))+' · '+time(x.next_visit):'Нет предстоящих визитов'}</p><form id="note-form" data-client="${esc(id)}"><label>Ваша личная заметка<textarea name="note" maxlength="2000">${esc(x.note)}</textarea></label><div class="form-error" role="alert"></div><button class="secondary">Сохранить заметку</button></form><h3>История записей</h3>${S.bookings.filter(b=>String(b.user_id)===String(id)).map(b=>`<button class="history-line history-button72" data-visit="${b.id}"><strong>${dateLabel(date(b.starts_at))} · ${time(b.starts_at)}</strong><span>${esc(b.service_name)}</span><small>${labels[b.status]} · ${money(b.price)}</small></button>`).join('')||'<p class="note">История пока пуста.</p>'}</div>`)}
'''
a=regex_once(a,r"function clientDetails\(id\)\{[\s\S]*?\nasync function reorder",new_details+"async function reorder",'client details')

# click handlers onboarding/preferences/docs/call
click_anchor="if(el.dataset.review){reviewEditor(el.dataset.review);return}\n"
click_extra="if(el.dataset.legal){legalDocSheet(el.dataset.legal);return}\nif(el.dataset.onboardLang){S.language=el.dataset.onboardLang;setStoredLanguage(S.language);await post('/v8/profile',{language:S.language});S.appSettings=await api('/v8/profile');showOnboarding('consent');return}\nif(el.id==='accept-consent'){await post('/v8/profile',{language:S.language,consent:true,...(S.pendingInvite?{role:'client',company_id:S.pendingInvite}:{})});S.appSettings=await api('/v8/profile');if(!S.pendingInvite&&!S.appSettings.role){showOnboarding('role');return}await init();return}\nif(el.dataset.onboardRole){await post('/v8/profile',{role:el.dataset.onboardRole});await init();return}\nif(el.dataset.language){S.language=el.dataset.language;setStoredLanguage(S.language);await post('/v8/profile',{language:S.language});S.appSettings=await api('/v8/profile');shellSignature='';await render({force:true});return}\nif(el.dataset.theme){applyTheme(el.dataset.theme);await post('/v8/profile',{theme:el.dataset.theme});S.appSettings=await api('/v8/profile');shellSignature='';await render({force:true});return}\nif(el.dataset.call){callClient(el.dataset.call);return}\n"
a=replace_once(a,click_anchor,click_anchor+click_extra,'click v8 handlers')
a=a.replace("if(el.dataset.messageClient){clientMessageEditor(el.dataset.messageClient);return}","if(el.dataset.messageClient){await clientMessageEditor(el.dataset.messageClient);return}")

# review refresh keeps server Telegram edit; better toast
