# index cache + css
idx=read('public/index.html').replace('?v=72','?v=80')
idx=replace_once(idx,'<link rel="stylesheet" href="/takt-v72.css?v=80">','<link rel="stylesheet" href="/takt-v72.css?v=80">\n<link rel="stylesheet" href="/takt-v8.css?v=80">','v8 css index')
