# ---- v8 visual system / dark mode ----
write('public/takt-v8.css',r'''/* Takt 8.0 — unified specialist/client polish, green accents and dark theme */
:root{--v8-green:#31bf72;--v8-green-2:#8de62d;--v8-green-soft:#eaf9f1;--v8-blue:#2857e6;--v8-ink:#152033;--v8-muted:#758094;--v8-border:#e5eaf1;--v8-card:#fff;--v8-bg:#f6f7fb}
html[data-theme="dark"]{color-scheme:dark;--v8-ink:#f2f5f8;--v8-muted:#9ba7b5;--v8-border:#28313d;--v8-card:#151b23;--v8-bg:#0d1117;--v8-green-soft:#173226}
html[data-theme="dark"] body,html[data-theme="dark"] .v2-main{background:#0d1117!important;color:var(--v8-ink)!important}html[data-theme="dark"] .v2-sidebar,html[data-theme="dark"] .v2-top,html[data-theme="dark"] .v2-bottom,html[data-theme="dark"] .editor-card,html[data-theme="dark"] .service-card,html[data-theme="dark"] .client-card72,html[data-theme="dark"] .visit-card,html[data-theme="dark"] .location-card,html[data-theme="dark"] .client-premium-head,html[data-theme="dark"] .client-review-preview,html[data-theme="dark"] .faq-card,html[data-theme="dark"] .legal-card,html[data-theme="dark"] .settings-section,html[data-theme="dark"] dialog{background:#151b23!important;color:#f2f5f8!important;border-color:#28313d!important;box-shadow:none!important}html[data-theme="dark"] input,html[data-theme="dark"] textarea,html[data-theme="dark"] select,html[data-theme="dark"] .picker-field,html[data-theme="dark"] .work-interval{background:#10161d!important;color:#f2f5f8!important;border-color:#303a47!important}html[data-theme="dark"] .secondary,html[data-theme="dark"] .text-button,html[data-theme="dark"] .client-call72,html[data-theme="dark"] .client-open72{background:#19212b!important;color:#d8e2ef!important;border-color:#34404f!important}html[data-theme="dark"] .note,html[data-theme="dark"] small,html[data-theme="dark"] .page-title p{color:#9ba7b5!important}html[data-theme="dark"] .client-note72,html[data-theme="dark"] .schedule-help{background:#111a20!important;color:#a8b5c4!important}html[data-theme="dark"] .calendar-day-list button{background:#151b23!important;border-color:#2c3541!important;color:#f2f5f8!important}
/* First start */
.onboarding-v8{width:min(720px,calc(100% - 28px));margin:clamp(24px,8vh,90px) auto;padding:clamp(24px,5vw,46px);border:1px solid var(--v8-border);border-radius:30px;background:var(--v8-card);box-shadow:0 30px 90px rgba(28,52,105,.10);text-align:center}.onboarding-mark{display:grid;place-items:center;width:58px;height:58px;margin:0 auto 18px;border-radius:18px;background:linear-gradient(145deg,var(--v8-blue),#1d43ba);color:#fff;font-size:34px;font-weight:850}.onboarding-v8 h1{font-size:clamp(30px,5vw,48px);margin:8px 0 10px}.onboarding-v8>p{max-width:600px;margin:0 auto 24px;color:var(--v8-muted);line-height:1.6}.language-grid,.role-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:22px}.language-grid button,.role-grid button{min-height:76px;padding:16px;border:1px solid var(--v8-border);border-radius:18px;background:var(--v8-card);color:var(--v8-ink);text-align:left}.language-grid button{display:flex;gap:12px;align-items:center}.language-grid button span{font-size:24px}.role-grid button{display:grid;gap:5px}.role-grid button strong{font-size:17px}.role-grid button span{color:var(--v8-muted);font-size:13px}.language-grid button:hover,.role-grid button:hover{border-color:var(--v8-green);box-shadow:0 0 0 3px color-mix(in srgb,var(--v8-green) 16%,transparent)}.legal-links{display:grid;gap:8px;margin:20px 0}.legal-links button{padding:13px 15px;border:1px solid var(--v8-border);border-radius:14px;background:var(--v8-card);color:var(--v8-blue);font-weight:700;text-align:left}.onboarding-v8>.primary{margin-top:8px}.onboarding-v8>small{display:block;margin-top:12px;color:var(--v8-muted)}
/* KPI + order */
.dashboard-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0 16px}.dashboard-kpis>div{min-height:82px;padding:14px 16px;border:1px solid var(--v8-border);border-radius:18px;background:var(--v8-card);display:grid;align-content:center;gap:3px}.dashboard-kpis span{font-size:12px;color:var(--v8-muted);font-weight:650}.dashboard-kpis strong{font-size:24px;letter-spacing:-.6px}.dashboard-kpis>div:first-child{border-color:#d8eadf}.dashboard-kpis>div:first-child strong{color:var(--v8-green)}.quick-heading{margin-top:16px!important}.quick-grid-v8{margin-bottom:18px}.quick-grid-v8 button{border-color:#dfe8e3!important}.quick-grid-v8 button:first-child{background:var(--v8-green-soft)!important;color:#198852!important}.attention-panel{margin-top:8px}.next72{margin-top:14px!important}
/* Clients use branded green */
.client-card72{border-color:#dfebe4!important}.client-status72{background:var(--v8-green-soft)!important;color:#218956!important}.client-status72.active{box-shadow:inset 0 0 0 1px #c8ecd8}.client-write72{background:linear-gradient(135deg,var(--v8-green),#22a65f)!important;color:#fff!important}.client-card72 .small-avatar.initials{background:var(--v8-green-soft)!important;color:#18844f!important}.client-detail72-contact{background:var(--v8-green-soft)!important;border-color:#ccebd9!important}
/* Perfectly centered weekday checkboxes */
.day-check{grid-template-columns:28px minmax(0,1fr)!important}.day-check input[type="checkbox"]{appearance:none!important;-webkit-appearance:none!important;width:20px!important;height:20px!important;min-width:20px!important;margin:0!important;padding:0!important;border:1.5px solid #b8c2cf!important;border-radius:6px!important;background:var(--v8-card)!important;display:grid!important;place-items:center!important;justify-self:center!important;align-self:center!important}.day-check input[type="checkbox"]:checked{background:var(--v8-green)!important;border-color:var(--v8-green)!important}.day-check input[type="checkbox"]:checked:after{content:'✓';display:block;color:#fff;font-size:13px;font-weight:900;line-height:1;transform:translateY(-.2px)}.work-day>.text-button{display:inline-flex!important;margin:8px 10px 0 0!important}.work-day>.text-button+ .text-button{margin-left:0!important}.manual-date-hint{padding:10px 12px;border-radius:12px;background:var(--v8-green-soft);color:#257a51}
/* Preferences/settings */
.settings-accent>summary:before{background:var(--v8-green)!important}.preference-control{display:grid;gap:9px;margin:14px 0}.preference-control>span{font-size:12px;font-weight:750;color:var(--v8-muted)}.choice-pills{display:flex;flex-wrap:wrap;gap:7px}.choice-pills button{padding:9px 12px;border:1px solid var(--v8-border);border-radius:999px;background:var(--v8-card);color:var(--v8-ink);font-weight:700}.choice-pills button.selected{border-color:var(--v8-green);background:var(--v8-green-soft);color:#16834c}.settings-links-v8{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.settings-links-v8 button{padding:13px;border:1px solid var(--v8-border);border-radius:14px;background:var(--v8-card);color:var(--v8-ink);font-weight:700}.settings-system-v8{border:1px solid var(--v8-border)!important;border-radius:18px!important;padding:14px 16px!important}.guide-highlight{border:1px solid color-mix(in srgb,var(--v8-green) 70%,#fff);border-radius:12px;padding:9px 13px;background:var(--v8-green-soft);color:#17844e;font-weight:800}
/* Profile/help/legal */
.profile-v8{display:grid!important;grid-template-columns:auto 1fr!important;gap:18px!important;align-items:center!important}.profile-settings-v8 h3{margin-top:0}.profile-link-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:12px}.profile-link-grid button{display:grid;gap:5px;padding:16px;border:1px solid var(--v8-border);border-radius:18px;background:var(--v8-card);color:var(--v8-ink);text-align:left}.profile-link-grid button span{font-size:12px;color:var(--v8-muted)}.faq-list{display:grid;gap:9px}.faq-card{border:1px solid var(--v8-border);border-radius:16px;background:var(--v8-card);padding:0 16px}.faq-card summary{padding:16px 0;font-weight:800;cursor:pointer}.faq-card p{margin:0 0 16px;color:var(--v8-muted);line-height:1.55}.help-actions-v8{display:flex;gap:8px;margin-top:16px}.legal-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.legal-card{padding:18px;border:1px solid var(--v8-border);border-radius:20px;background:var(--v8-card)}.legal-card h2{font-size:18px}.legal-card p{color:var(--v8-muted);line-height:1.5;min-height:86px}.legal-version{color:var(--v8-muted);font-size:12px;margin-top:14px}.legal-sheet p{line-height:1.6;color:var(--v8-muted)}
/* Subscription */
.subscription-v8{padding:24px;border:1px solid #dfe6f3;border-radius:26px;background:linear-gradient(150deg,#fff 0%,#f8fbff 62%,#effaf4 100%)}.subscription-v8-top{display:flex;justify-content:space-between;align-items:flex-start;gap:18px}.subscription-v8-top h2{font-size:36px;margin:5px 0}.subscription-v8-top p{margin:0;color:var(--v8-muted)}.subscription-value{margin:20px 0;padding:18px;border-radius:18px;background:#152b5c;color:#fff}.subscription-value .eyebrow{color:#a9c2ff}.subscription-value h3{margin:6px 0;font-size:20px}.subscription-value p{margin:0;color:#dce7ff}.subscription-value strong{color:var(--v8-green-2)}.subscription-safe{padding:12px 14px;border-radius:14px;background:#fff4f4;color:#9a3942}.subscription-v8.expired{background:linear-gradient(150deg,#fff,#fff8f8)}html[data-theme="dark"] .subscription-v8{background:linear-gradient(150deg,#151b23,#111b1a);border-color:#2b3643}html[data-theme="dark"] .subscription-value{background:#101d38}
/* Client cabinet alignment with specialist */
.client-premium-head,.client-review-preview,.client-location,.premium-service{border-color:var(--v8-border)!important}.client-premium-head{box-shadow:0 18px 45px rgba(31,55,105,.07)!important}.client-rating{background:var(--v8-green-soft)!important;color:#1d8752!important}.premium-service .primary{background:linear-gradient(135deg,var(--v8-blue),#1d43bd)!important}
@media(max-width:760px){.language-grid,.role-grid{grid-template-columns:1fr}.onboarding-v8{margin:12px auto;padding:24px 18px;border-radius:24px}.dashboard-kpis{grid-template-columns:repeat(3,1fr);gap:6px}.dashboard-kpis>div{min-height:70px;padding:10px}.dashboard-kpis span{font-size:10px}.dashboard-kpis strong{font-size:18px}.settings-links-v8,.profile-link-grid,.legal-cards{grid-template-columns:1fr}.profile-v8{grid-template-columns:auto 1fr!important}.subscription-v8{padding:17px}.subscription-v8-top{display:grid}.subscription-v8-top h2{font-size:30px}.help-actions-v8{display:grid}.choice-pills{display:grid;grid-template-columns:1fr 1fr}.next72-actions{grid-template-columns:repeat(3,1fr)!important;display:grid!important}.next72-actions button{min-width:0!important;padding:9px 6px!important;font-size:12px}.work-day>.text-button{display:flex!important;width:100%!important;justify-content:flex-start!important;margin:6px 0!important}}
''')

# package/version/check
pkg=json.loads(read('package.json'));pkg['version']='8.0.0';pkg['scripts']['check']=pkg['scripts']['check'].replace('public/app-v2.js','public/app-v2.js && node --check public/i18n.js') if 'public/i18n.js' not in pkg['scripts']['check'] else pkg['scripts']['check'];write('package.json',json.dumps(pkg,ensure_ascii=False,separators=(',',':'))+'\n')
lock=json.loads(read('package-lock.json'));lock['version']='8.0.0';lock.get('packages',{}).get('',{})['version']='8.0.0';write('package-lock.json',json.dumps(lock,ensure_ascii=False,indent=2)+'\n')

